const input = $input.first().json;
const jobId = 'doc-ai-' + Date.now() + '-' + Math.random().toString(36).substr(2, 8);

// Pass through all original fields + attach jobId & callbackUrl
const callbackUrl = input.body?.callbackUrl || input.callbackUrl || null;

console.log('=== New SDR Job ===');
console.log('Job ID:', jobId);
console.log('Client:', input.body?.clientName || input.clientName || 'Unknown');
console.log('Callback URL:', callbackUrl || '(none provided)');

return [{
  json: {
    ...input,
    jobId,
    callbackUrl,
    jobStartedAt: new Date().toISOString()
  }
}];

// Extract input data
// NOTE: $input here is Set Webhook Config output (DOCX_WEBHOOK_URL only).
// Read the original webhook body directly from Webhook Trigger node.
const webhookJson = $('Webhook Trigger').first().json;

let clientName, fileBase64, baseSheetName;

if (webhookJson.body) {
  clientName = webhookJson.body.clientName;
  fileBase64 = webhookJson.body.fileBase64;
  baseSheetName = webhookJson.body.baseSheetName;
} else {
  clientName = webhookJson.clientName;
  fileBase64 = webhookJson.fileBase64;
  baseSheetName = webhookJson.baseSheetName;
}

if (!clientName || !fileBase64 || !baseSheetName) {
  throw new Error('Missing required fields: clientName, fileBase64, baseSheetName');
}

return [{
  json: {
    clientName,
    fileBase64,
    baseSheetName
  }
}];

// Convert base64 to binary
const data = $input.first().json;
const base64Data = data.fileBase64;

const binaryData = {
  data: base64Data,
  mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  fileName: 'original.xlsx'
};

return [{
  json: {
    clientName: data.clientName,
    baseSheetName: data.baseSheetName
  },
  binary: {
    file: binaryData
  }
}];

// Fill-Down: ExcelJS (n8n SpreadsheetFile) returns null for all rows after
// the first in a merged cell range. This node carries the last non-empty value
// forward for each hierarchical column so downstream nodes see complete data.

const items = $input.all();
const allCols = items.length > 0 ? Object.keys(items[0].json) : [];

// Detect hierarchical column names dynamically (case-insensitive partial match)
const HIER_PATTERNS = [
  ['business goal', 'goal', '\uBE44\uC988\uB2C8\uC2A4 \uBAA9\uD45C'],
  ['strategy', '\uC804\uB7B5'],
  ['initiative', '\uC774\uB2C8\uC154\uD2F0\uBE0C', '\uCD94\uC9C4'],
  ['tactic', '\uC804\uC220'],
  ['kpi', 'key performance'],
];

const fillCols = [];
for (const patterns of HIER_PATTERNS) {
  for (const col of allCols) {
    const c = col.toLowerCase();
    if (patterns.some(p => c.includes(p))) { fillCols.push(col); break; }
  }
}

console.log('=== Fill Down Merged Cells ===');
console.log('Columns to fill down:', fillCols);

const lastValues = {};
fillCols.forEach(col => { lastValues[col] = ''; });

return items.map(item => {
  const row = { ...item.json };
  for (const col of fillCols) {
    const val = row[col];
    const isEmpty = val === null || val === undefined || String(val).trim() === '';
    if (!isEmpty) {
      lastValues[col] = String(val).trim();
    } else {
      row[col] = lastValues[col];
    }
  }
  return { json: row };
});

// Parse requirements—supports HIERARCHICAL BRD (Business Goal/Strategy/Initiative/Tactics/KPI/Business Capability)
// and legacy REQ_ID format (Requirement ID / Category / Business Requirement / Notes).

const items = $input.all();
const clientName = $('Create Binary').first().json.clientName;

console.log('=== Processing Requirements ===');
console.log('Client:', clientName);
console.log('Rows received:', items.length);

if (items.length === 0) {
  throw new Error('No rows received from the sheet. Check baseSheetName and file format.');
}

const allCols = Object.keys(items[0].json);

function findCol(patterns) {
  for (const col of allCols) {
    const c = col.toLowerCase();
    if (patterns.some(p => c.includes(p))) return col;
  }
  return null;
}

const capabilityCol = findCol(['business capability', 'capability', '\uC5ED\uB7C9']);
const goalCol       = findCol(['business goal', 'goal', '\uBAA9\uD45C']);
const strategyCol   = findCol(['strategy', '\uC804\uB7B5']);
const initiativeCol = findCol(['initiative', '\uC774\uB2C8\uC154\uD2F0\uBE0C', '\uCD94\uC9C4']);
const tacticsCol    = findCol(['tactic', '\uC804\uC220']);
const kpiCol        = findCol(['kpi', 'key performance']);

const isHierarchical = !!(capabilityCol && goalCol);
console.log('BRD format:', isHierarchical ? 'HIERARCHICAL' : 'REQ_ID');
console.log('Columns:', { goalCol, strategyCol, initiativeCol, tacticsCol, kpiCol, capabilityCol });

// ── HIERARCHICAL MODE ────────────────────────────────────────────────────────
if (isHierarchical) {
  const requirements = [];
  let reqCounter = 0;

  for (const item of items) {
    const row = item.json;
    const capability = capabilityCol ? String(row[capabilityCol] || '').trim() : '';
    if (!capability) continue;

    reqCounter++;
    requirements.push({
      id:           `REQ-${String(reqCounter).padStart(3, '0')}`,
      business_goal: goalCol       ? String(row[goalCol]       || '').trim() : '',
      strategy:      strategyCol   ? String(row[strategyCol]   || '').trim() : '',
      initiative:    initiativeCol ? String(row[initiativeCol] || '').trim() : '',
      tactic:        tacticsCol    ? String(row[tacticsCol]    || '').trim() : '',
      kpi:           kpiCol        ? String(row[kpiCol]        || '').trim() : '',
      capability,
    });
  }

  console.log('Requirements (hierarchical) parsed:', requirements.length);

  const allReqIds = requirements.map(r => r.id);

  let formattedRequirements = '# BUSINESS REQUIREMENTS DOCUMENT\n\n';
  formattedRequirements += `**Client:** ${clientName}\n`;
  formattedRequirements += `**Total Business Capabilities:** ${requirements.length}\n\n`;

  formattedRequirements += '```\n=== REQUIREMENT INVENTORY ===\n';
  formattedRequirements += `Total: ${requirements.length} requirements detected\n`;
  formattedRequirements += `All req_ids: ${allReqIds.join(', ')}\n`;
  formattedRequirements += '\u26a0\ufe0f  You MUST map EVERY ID listed above to at least one variable or OOTB entry.\n';
  formattedRequirements += 'Zero unmapped requirements are acceptable. No exceptions.\n';
  formattedRequirements += '=============================\n```\n\n';

  formattedRequirements += '## BUSINESS REQUIREMENTS HIERARCHY\n\n';

  // Nested grouping: Business Goal → Strategy → Initiative → Tactic
  const bgGroups = {};
  for (const req of requirements) {
    const bg  = req.business_goal || '(No Business Goal)';
    const st  = req.strategy      || '(No Strategy)';
    const ini = req.initiative    || '(No Initiative)';
    const tac = req.tactic        || '(No Tactic)';
    if (!bgGroups[bg])             bgGroups[bg] = {};
    if (!bgGroups[bg][st])         bgGroups[bg][st] = {};
    if (!bgGroups[bg][st][ini])    bgGroups[bg][st][ini] = {};
    if (!bgGroups[bg][st][ini][tac]) bgGroups[bg][st][ini][tac] = [];
    bgGroups[bg][st][ini][tac].push(req);
  }

  for (const [bg, strategies] of Object.entries(bgGroups)) {
    formattedRequirements += `## Business Goal: ${bg}\n\n`;
    for (const [st, initiatives] of Object.entries(strategies)) {
      formattedRequirements += `### Strategy: ${st}\n\n`;
      for (const [ini, tactics] of Object.entries(initiatives)) {
        formattedRequirements += `#### Initiative: ${ini}\n\n`;
        for (const [tac, reqs] of Object.entries(tactics)) {
          formattedRequirements += `##### Tactic: ${tac}\n`;
          if (reqs[0] && reqs[0].kpi) formattedRequirements += `- **KPI:** ${reqs[0].kpi}\n`;
          formattedRequirements += '\n';
          for (const req of reqs) {
            formattedRequirements += `**[${req.id}]** ${req.capability}\n\n`;
          }
        }
      }
    }
  }

  return [{
    json: {
      clientName,
      totalRequirements: requirements.length,
      allReqIds,
      categories: [...new Set(requirements.map(r => r.business_goal).filter(Boolean))],
      requirements,
      formattedRequirements,
    }
  }];
}

// ── REQ_ID MODE (legacy — preserved for non-hierarchical BRDs) ───────────────
const FIELD_ALIASES = {
  req_id:       ['requirement id', 'req id', 'req_id', 'id#', 'no.', '\uBC88\uD638', 'id'],
  category:     ['category', '\uCE74\uD14C\uACE0\uB9AC', 'type', 'section', '\uBD84\uB958'],
  business_req: ['business requirement', 'business req', 'requirement', '\uC694\uAD6C\uC0AC\uD56D', 'description', 'question'],
  notes:        ['additional notes', 'notes', '\uBE44\uACE0', 'remarks', 'comment', 'comments', '\uBA54\uBAA8', 'feedback']
};

function resolveFieldAliases(keys) {
  const result = {};
  const keyLower = keys.map(k => ({ orig: k, low: k.toLowerCase() }));
  for (const [field, aliases] of Object.entries(FIELD_ALIASES)) {
    for (const alias of aliases) {
      const hit = keyLower.find(k => k.low.includes(alias) || alias.includes(k.low));
      if (hit) { result[field] = hit.orig; break; }
    }
  }
  return result;
}

let headerMap = {};
for (const item of items) {
  const keys = Object.keys(item.json).filter(k => item.json[k] !== null && item.json[k] !== undefined && String(item.json[k]).trim() !== '');
  if (keys.length >= 2) {
    const candidate = resolveFieldAliases(Object.keys(item.json));
    if (Object.keys(candidate).length >= 2) { headerMap = candidate; break; }
  }
}

if (Object.keys(headerMap).length === 0) {
  headerMap = { req_id: 'Requirement ID', category: 'Category', business_req: 'Business Requirement', notes: 'Additional Notes' };
}

console.log('Field mapping (REQ_ID mode):', JSON.stringify(headerMap));

const requirements = [];
const categoryGroups = {};

for (let index = 0; index < items.length; index++) {
  const row = items[index].json;
  const reqId    = headerMap.req_id       ? row[headerMap.req_id]       : null;
  const category = headerMap.category     ? row[headerMap.category]     : null;
  const bizReq   = headerMap.business_req ? row[headerMap.business_req] : null;
  const notes    = headerMap.notes        ? row[headerMap.notes]        : null;

  if (!reqId && !category && !bizReq) continue;

  const requirement = {
    id: reqId ? String(reqId).trim() : `REQ-${String(index + 1).padStart(3, '0')}`,
    category: category ? String(category).trim() : 'General',
    requirement: bizReq ? String(bizReq).trim() : '(description not specified)',
    notes: notes ? String(notes).trim() : ''
  };
  requirements.push(requirement);

  if (!categoryGroups[requirement.category]) categoryGroups[requirement.category] = [];
  categoryGroups[requirement.category].push(requirement);
}

const allReqIds = requirements.map(r => r.id);
let formattedRequirements = '# BUSINESS REQUIREMENTS DOCUMENT\n\n';
formattedRequirements += `**Client:** ${clientName}\n`;
formattedRequirements += `**Total Requirements:** ${requirements.length}\n\n`;

formattedRequirements += '```\n=== REQUIREMENT INVENTORY ===\n';
formattedRequirements += `Total: ${requirements.length} requirements detected\n`;
formattedRequirements += `All req_ids: ${allReqIds.join(', ')}\n`;
formattedRequirements += '\u26a0\ufe0f  You MUST map EVERY ID listed above to at least one variable or OOTB entry.\n';
formattedRequirements += 'Zero unmapped requirements are acceptable. No exceptions.\n';
formattedRequirements += '=============================\n```\n\n';

formattedRequirements += '## REQUIREMENTS BY CATEGORY\n\n';

Object.keys(categoryGroups).forEach(category => {
  const reqs = categoryGroups[category];
  formattedRequirements += `### ${category} (${reqs.length} requirements)\n\n`;
  reqs.forEach(req => {
    formattedRequirements += `**[${req.id}]**\n`;
    formattedRequirements += `- **Requirement:** ${req.requirement}\n`;
    if (req.notes) formattedRequirements += `- **Notes:** ${req.notes}\n`;
    formattedRequirements += '\n';
  });
});

console.log('Requirements parsed:', requirements.length);
return [{
  json: {
    clientName,
    totalRequirements: requirements.length,
    allReqIds,
    categories: Object.keys(categoryGroups),
    requirements,
    formattedRequirements,
  }
}];

// ── TPM Monitor — log estimated token consumption ──────────────────────
const parseOut = $input.first().json;
const sdr = parseOut.sdr || {};

const evarCount  = (sdr.evars || []).length;
const propsCount = (sdr.props || []).length;
const eventsCount= (sdr.events || []).length;
const dlmCount   = (sdr.data_layer_map || []).length;
const brdCount   = (sdr.brd_traceability || []).length;

// Rough token estimates for downstream TSD call
const estTSDInput = (evarCount * 25) + (propsCount * 20) + (eventsCount * 25) + 2000;
const tpmWarning  = estTSDInput > 20000;

console.log('=== TPM Monitor (Post-Merge) ===');
console.log(`eVars: ${evarCount} | Props: ${propsCount} | Events: ${eventsCount}`);
console.log(`DL Map: ${dlmCount} | BRD Trace: ${brdCount}`);
console.log(`Est. TSD call input tokens: ~${estTSDInput}`);
if (tpmWarning) console.warn('⚠️ TSD call may approach TPM limit — consider splitting');

return [{ json: { ...parseOut, tpm_monitor: { evarCount, propsCount, eventsCount, estTSDInput, tpmWarning } } }];

const parseNode = $('Parse Requirements').first();
if (!parseNode?.json) return { error: 'No requirements data' };
return parseNode.json.formattedRequirements;

const rawOutput = $('SDR eVars Agent').first().json.output || '';
try {
  const m = rawOutput.match(/\{[\s\S]*\}/);
  const data = m ? JSON.parse(m[0]) : JSON.parse(rawOutput);
  const part1 = data.sdr_part1 || data.sdr || data;
  const evars = part1.evars || [];
  const ootb  = part1.section_a_ootb || [];

  // Compact format: one line per variable (70-80% token reduction)
  const evarLines = evars.map(e =>
    `${e.variable}=${e.variable_name}|${e.group}|exp:${e.expiration}|alloc:${e.allocation}|merch:${e.merchandising}`
  ).join('\n');

  const ootbNames = ootb.map(v => v.variable).join(', ');

  return `EVARS_PART1 (${evars.length} custom eVars):\n${evarLines}\n\nOOTB_VARS: ${ootbNames}`;
} catch(e) {
  return 'ERROR parsing Part 1 eVars: ' + e.message;
}

const parseNode = $('Parse Requirements').first();
if (!parseNode?.json) return { error: 'No requirements data' };
return parseNode.json.formattedRequirements;

