// ── Merge Part 1 (eVars) and Part 2 (Props/Events) into a unified SDR ──────
const rawP1 = $('SDR eVars Agent').first().json.output || '';
const rawP2 = $('SDR Props Events Agent').first().json.output || '';

function safeParse(raw) {
  try {
    const m = raw.match(/\{[\s\S]*\}/);
    return m ? JSON.parse(m[0]) : JSON.parse(raw);
  } catch(e) {
    throw new Error('JSON parse failed: ' + e.message + ' | snippet: ' + raw.slice(0, 300));
  }
}

const data1 = safeParse(rawP1);
const data2 = safeParse(rawP2);

const part1 = data1.sdr_part1 || data1.sdr || data1;
const part2 = data2.sdr_part2 || data2.sdr || data2;

const sectionA    = part1.section_a_ootb || [];
const evars       = part1.evars || [];
const props       = part2.props || [];
const events      = part2.events || [];
const dlMap       = part2.data_layer_map || [];
const brdTrace    = part2.brd_traceability || [];
const metadata    = part1.metadata || {};

const customEvents = events.filter(e => !['OOTB Commerce','OOTB Metric'].includes(e.event_type));

const merged = {
  sdr: {
    metadata: {
      client: metadata.client || $('Parse Requirements').first().json.clientName,
      vertical: metadata.vertical || 'Retail / E-Commerce',
      platform: 'Adobe Analytics + AEP Web SDK',
      version: '1.0',
      date: new Date().toISOString().slice(0, 10),
      brd_reference: metadata.brd_reference || 'GSSHOP_BRD.xlsx'
    },
    summary: {
      section_a_ootb_count: sectionA.length,
      section_b_evars_count: evars.length,
      section_b_props_count: props.length,
      section_b_events_count: customEvents.length
    },
    section_a_ootb: sectionA,
    evars: evars,
    props: props,
    events: events,
    data_layer_map: dlMap,
    brd_traceability: brdTrace
  }
};

console.log('=== Merge SDR Parts ===');
console.log('OOTB:', sectionA.length, '| eVars:', evars.length, '| Props:', props.length,
  '| Events total:', events.length, '(custom:', customEvents.length + ')',
  '| DLM:', dlMap.length, '| Traceability:', brdTrace.length);

return [{ json: { output: JSON.stringify(merged) } }];

// Parse SDR JSON output (v1.0 structure: sdr.section_a_ootb, sdr.evars, sdr.props, sdr.events, etc.)
const rawOutput = $input.first().json.output || $input.first().json.text;

let sdrData;
try {
  const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
  sdrData = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(rawOutput);
} catch (error) {
  throw new Error('Failed to parse SDR output: ' + error.message);
}

// Support v1.0 structure (sdrData.sdr.*) and legacy flat structure
const sdr = sdrData.sdr || sdrData;

if (!sdr.evars || !sdr.props || !sdr.events) {
  throw new Error('SDR missing required fields: evars, props, or events');
}

const sectionA     = sdr.section_a_ootb || [];
const dataLayerMap = sdr.data_layer_map  || [];
const brdTraceability = sdr.brd_traceability || [];

const originalBinary = $('Create Binary').first().binary.file;
const clientName     = $('Parse Requirements').first().json.clientName;
const allInputReqIds = $('Parse Requirements').first().json.allReqIds || [];

// ── Validation: Numbering Continuity ────────────────────────────────────────
const warnings = [];

function checkNumbering(items, prefix, field) {
  // Extract numeric suffix from variable field (e.g. "eVar3" → 3)
  const nums = items
    .map(item => {
      const val = item[field] || '';
      const m = String(val).match(new RegExp(`^${prefix}(\\d+)$`, 'i'));
      return m ? parseInt(m[1], 10) : null;
    })
    .filter(n => n !== null)
    .sort((a, b) => a - b);

  if (nums.length === 0) return;

  // Check for gaps
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] !== nums[i - 1] + 1) {
      warnings.push(`${prefix} numbering gap: ${prefix}${nums[i-1]} → ${prefix}${nums[i]} (expected ${prefix}${nums[i-1]+1})`);
    }
  }
  // Check for duplicates
  const uniqueNums = new Set(nums);
  if (uniqueNums.size !== nums.length) {
    warnings.push(`${prefix} contains duplicate numbers`);
  }
  // Check starts at 1
  if (nums[0] !== 1) {
    warnings.push(`${prefix} numbering does not start at 1 (starts at ${prefix}${nums[0]})`);
  }
}

checkNumbering(sdr.evars, 'eVar', 'variable');
checkNumbering(sdr.props, 'prop', 'variable');
// Custom events only (filter out OOTB events)
const customEvents = sdr.events.filter(e => !['OOTB Commerce', 'OOTB Metric'].includes(e.event_type));
checkNumbering(customEvents, 'event', 'event');

// ── Validation: Requirement Coverage ────────────────────────────────────────
if (allInputReqIds.length > 0) {
  // Collect all req_ids that appear in the SDR output
  const coveredIds = new Set();
  [...sectionA, ...sdr.evars, ...sdr.props, ...sdr.events].forEach(item => {
    if (item.req_id) coveredIds.add(String(item.req_id).trim());
  });

  const uncovered = allInputReqIds.filter(id => !coveredIds.has(String(id).trim()));
  if (uncovered.length > 0) {
    warnings.push(`Uncovered requirements: ${uncovered.join(', ')}`);
  }

  const coveragePct = allInputReqIds.length > 0
    ? Math.round(((allInputReqIds.length - uncovered.length) / allInputReqIds.length) * 100)
    : 100;

  var validation = {
    numbering_ok: warnings.filter(w => w.includes('numbering')).length === 0,
    coverage_pct: coveragePct,
    uncovered_req_ids: uncovered,
    warnings: warnings
  };
} else {
  var validation = {
    numbering_ok: warnings.filter(w => w.includes('numbering')).length === 0,
    coverage_pct: 100,
    uncovered_req_ids: [],
    warnings: warnings
  };
}

if (warnings.length > 0) {
  console.warn('⚠️  SDR Validation Warnings:\n' + warnings.map(w => '  - ' + w).join('\n'));
} else {
  console.log('✅ SDR Validation passed: numbering OK, coverage 100%');
}

// ── Build TSD Webhook Payload ─────────────────────────────────────────────
const tsdWebhookPayload = {
  body: [
    {
      clientName: clientName,
      sdr: {
        metadata: sdr.metadata || {
          client: clientName,
          vertical: 'General',
          platform: 'Adobe Analytics + AEP Web SDK',
          version: '1.0',
          date: new Date().toISOString().slice(0, 10)
        },
        summary: sdr.summary || {
          section_a_ootb_count: sectionA.length,
          section_b_evars_count: sdr.evars.length,
          section_b_props_count: sdr.props.length,
          section_b_events_count: customEvents.length
        },
        section_a_ootb:  sectionA,
        evars:           sdr.evars,
        props:           sdr.props,
        events:          sdr.events,
        data_layer_map:  dataLayerMap,
        brd_traceability: brdTraceability
      }
    }
  ]
};

return [{
  json: {
    success: true,
    clientName: clientName,
    originalFileBase64: originalBinary.data,
    sdr: sdr,
    stats: {
      ootb:               sectionA.length,
      evars:              sdr.evars.length,
      props:              sdr.props.length,
      events:             sdr.events.length,
      custom_events:      customEvents.length,
      data_layer_entries: dataLayerMap.length,
      brd_tactics:        brdTraceability.length
    },
    validation: validation,
    tsdWebhookPayload: tsdWebhookPayload
  }
}];

// ── SDR Excel Generator v3.0 (OOXML) ─────────────────────────────────────────
// Expected template match: sdr_expected.xlsx
// - Col A: 3pt spacer, data starts at col B
// - Row 1: Title (navy #1F4E79, white bold 14pt, merged B→last)
// - Row 2: Headers (blue #2E75B6, white bold 9pt)
// - Section headers: "▶  SECTION X  —  ..." (navy bg)
// - Group sub-headers: "▶  GroupName" (light blue bg, blue text)
// - Data rows: 45pt height, wrap, vertical top
// - Spacer rows: 6pt between groups/sections

const parseOut = $('Parse SDR Output').first().json;
const sdr      = parseOut.sdr;
const clientName = parseOut.clientName || sdr?.metadata?.client || 'Client';

if (!sdr || (!sdr.evars && !sdr.section_a_ootb)) {
  throw new Error('SDR data missing in Generate SDR Excel input');
}

// ── CRC32 ────────────────────────────────────────────────────────────────────
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    t[i] = c;
  }
  return t;
})();
function crc32(buf) {
  let c = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xFF] ^ (c >>> 8);
