function cell(colIdx, rowNum, val, style) {
  // colIdx: 0=A,1=B... rowNum: 1-based. Inline string cell.
  return `<c r="${col(colIdx)}${rowNum}" t="inlineStr" s="${style}"><is><t>${x(val)}</t></is></c>`;
