// ── Group helper ──────────────────────────────────────────────────────────────
function groupItems(items, field) {
  const order=[]; const map=new Map();
  for (const item of (items||[])) {
    const g = (item[field]||'Other').trim();
    if (!map.has(g)) { map.set(g,[]); order.push(g); }
    map.get(g).push(item);
  }
  return order.map(name=>({name, items:map.get(name)}));
}

// ── buildSheet ────────────────────────────────────────────────────────────────
// colWidths: [colA_spacer_width, colB_width, colC_width, ...]
// rows: [{type: 'title'|'header'|'section'|'group'|'data'|'spacer', ...}]
// Styles: 0=data 1=header 2=section 3=group 4=title
function buildSheet(colWidths, rows) {
  const nCols = colWidths.length;
  const lastDataCol = col(nCols-1);
  const colXml = colWidths.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('');
  const merges=[];
  let rn=1;
  const rowXml = rows.map(r => {
    let out;
    if (r.type==='spacer') {
      out=`<row r="${rn}" ht="6" customHeight="1"/>`;
    } else if (r.type==='title') {
      merges.push(`<mergeCell ref="B${rn}:${lastDataCol}${rn}"/>`);
      out=`<row r="${rn}" ht="28" customHeight="1">${cell(1,rn,r.label,4)}</row>`;
    } else if (r.type==='header') {
      out=`<row r="${rn}" ht="22" customHeight="1">${r.cols.map((v,ci)=>cell(ci+1,rn,v,1)).join('')}</row>`;
    } else if (r.type==='section') {
      merges.push(`<mergeCell ref="B${rn}:${lastDataCol}${rn}"/>`);
      out=`<row r="${rn}" ht="18" customHeight="1">${cell(1,rn,r.label,2)}</row>`;
    } else if (r.type==='group') {
      merges.push(`<mergeCell ref="B${rn}:${lastDataCol}${rn}"/>`);
      out=`<row r="${rn}" ht="18" customHeight="1">${cell(1,rn,r.label,3)}</row>`;
    } else if (r.type==='data') {
      out=`<row r="${rn}" ht="45" customHeight="1">${r.cols.map((v,ci)=>cell(ci+1,rn,v,0)).join('')}</row>`;
    } else {
      out=`<row r="${rn}"/>`;
    }
    rn++; return out;
  }).join('');
  const mergeXml = merges.length?`<mergeCells count="${merges.length}">${merges.join('')}</mergeCells>`:'';
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols>${colXml}</cols><sheetData>${rowXml}</sheetData>${mergeXml}</worksheet>`;
}

