// ── 01_eVars ──────────────────────────────────────────────────────────────────
function buildEvarsSheet(clientName, sectionA, evars) {
  const colWidths=[3,10,12,22,42,18,28,18,20,16,16];
  const headers=['Req ID','Variable','Variable Name','Variable Description','Value Format / Example','Allocation','Expiration','Merchandising','Capture Method','Group'];
  const toRow = v=>({type:'data',cols:[v.req_id||'',v.variable||'',v.variable_name||'',v.variable_description||'',v.value_format||'',v.allocation||'N/A (OOTB)',v.expiration||'N/A (OOTB)',v.merchandising||'n/a',v.capture_method||'',v.group||'']});
  const rows=[];
  rows.push({type:'title',label:`eVar (Conversion Variable) Mapping — ${clientName} Adobe Analytics SDR v1.0`});
  rows.push({type:'header',cols:headers});
  // Section A
  rows.push({type:'section',label:'▶  SECTION A  —  OOTB Variables  |  No custom eVar slot required'});
  for(const v of (sectionA||[])) rows.push(toRow(v));
  rows.push({type:'spacer'});
  // Section B with groups
  rows.push({type:'section',label:'▶  SECTION B  —  Custom eVars  |  Allocated eVar slots'});
  const groups = groupItems(evars,'group');
  let first=true;
  for(const {name,items} of groups){
    if(!first) rows.push({type:'spacer'});
    first=false;
    rows.push({type:'group',label:`▶  ${name}`});
    for(const v of items) rows.push(toRow(v));
  }
  return buildSheet(colWidths,rows);
}

