const CT=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet3.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet4.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet5.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet6.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>`;
const RR=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`;
const WB=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="00_Cover" sheetId="1" r:id="rId1"/><sheet name="01_eVars" sheetId="2" r:id="rId2"/><sheet name="02_Props" sheetId="3" r:id="rId3"/><sheet name="03_Events" sheetId="4" r:id="rId4"/><sheet name="04_DataLayer_Map" sheetId="5" r:id="rId5"/><sheet name="05_BRD_Requirements" sheetId="6" r:id="rId6"/></sheets></workbook>`;
const WR=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet3.xml"/><Relationship Id="rId4" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet4.xml"/><Relationship Id="rId5" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet5.xml"/><Relationship Id="rId6" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet6.xml"/><Relationship Id="rId7" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`;

// ── Build sheets ──────────────────────────────────────────────────────────────
const meta = {
  client: clientName,
  vertical: sdr.metadata?.vertical||'Retail / E-Commerce',
  platform: sdr.metadata?.platform||'Adobe Analytics + AEP Web SDK',
  version: sdr.metadata?.version||'v1.0',
  date: sdr.metadata?.date||new Date().toISOString().slice(0,10),
  brd_reference: sdr.metadata?.brd_reference||''
};
const evars = sdr.evars||[];
const props  = sdr.props||[];
const events = sdr.events||[];
const ootbE  = events.filter(e=>['OOTB Commerce','OOTB Metric'].includes(e.event_type));
const custE  = events.filter(e=>!['OOTB Commerce','OOTB Metric'].includes(e.event_type));
const evarGroupNames = [...new Set(evars.map(v=>v.group||'').filter(Boolean))].slice(0,5).join(' | ');
const propGroupNames = [...new Set(props.map(v=>v.group||'').filter(Boolean))].slice(0,5).join(' | ');
const eventGroupNames= [...new Set(custE.map(e=>e.group||'').filter(Boolean))].slice(0,5).join(' | ');

const counts={evarCount:evars.length,propCount:props.length,customEventCount:custE.length,ootbEventCount:ootbE.length,evarGroupNames,propGroupNames,eventGroupNames};

const s00 = buildCoverSheet(meta,counts);
const s01 = buildEvarsSheet(clientName, sdr.section_a_ootb||[], evars);
const s02 = buildPropsSheet(clientName, props);
const s03 = buildEventsSheet(clientName, events);
const s04 = buildDataLayerSheet(sdr.data_layer_map||[]);
const s05 = buildBRDSheet(sdr.brd_traceability||[]);

// ── Assemble ZIP ──────────────────────────────────────────────────────────────
const entries=[
  makeEntry('[Content_Types].xml',CT),
  makeEntry('_rels/.rels',RR),
  makeEntry('xl/workbook.xml',WB),
  makeEntry('xl/_rels/workbook.xml.rels',WR),
  makeEntry('xl/styles.xml',ST),
  makeEntry('xl/worksheets/sheet1.xml',s00),
  makeEntry('xl/worksheets/sheet2.xml',s01),
  makeEntry('xl/worksheets/sheet3.xml',s02),
  makeEntry('xl/worksheets/sheet4.xml',s03),
  makeEntry('xl/worksheets/sheet5.xml',s04),
  makeEntry('xl/worksheets/sheet6.xml',s05),
];
const zipBuf = buildZip(entries);
const b64 = zipBuf.toString('base64');
const _now = new Date();
const _ts  = _now.toISOString()
              .replace(/[-:T]/g, '')
              .replace(/\.\d+Z$/, '')
              .substring(0, 14);  // YYYYMMDDHHMMSS
const _tsFormatted = _ts.substring(0,8) + '_' + _ts.substring(8); // YYYYMMDD_HHMMSS
const fileName = `${clientName}_SDR_${_tsFormatted}.xlsx`;

console.log(`✅ SDR Excel v3.0 generated: ${fileName} (${zipBuf.length} bytes) | eVars:${evars.length} Props:${props.length} Events:${events.length}(OOTB:${ootbE.length})`);

return [{
  json: {clientName, success:true, format:'OOXML', fileName, sheets:['00_Cover','01_eVars','02_Props','03_Events','04_DataLayer_Map','05_BRD_Requirements']},
  binary: {data:{data:b64, mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName}}
}];

// Check if an existing SDR folder was found in Google Drive
const results = $('Find SDR Folder').all();
const found = results.find(item => item.json && item.json.id && item.json.mimeType === 'application/vnd.google-apps.folder');
if (found) {
  console.log('✅ Existing SDR folder found:', found.json.id, found.json.name);
  return [{ json: { id: found.json.id, name: found.json.name, folderExists: true } }];
}
console.log('ℹ️  No existing SDR folder — will create new one');
return [{ json: { folderExists: false, id: null } }];

// Combine SDR Excel binary with Google Drive folder ID
// Handles: missing folderId (Create SDR Folder failed) and missing binary (ExcelJS failed)

const inputItem = $input.first().json;

// ── Check 1: Did Create SDR Folder succeed? ──────────────────────
const folderId = inputItem.id;
if (!folderId) {
  const reason = inputItem.error?.message
    || inputItem.message
    || JSON.stringify(inputItem).slice(0, 150);
  console.error('SDR Folder creation failed:', reason);
  return [{ json: { _sdr_upload_skipped: true, reason: 'Folder creation failed: ' + reason } }];
}

// ── Check 2: Did Generate SDR Excel v1 produce binary? ──────────
const sdrNode = $('Generate SDR Excel v1').first();

if (!sdrNode || !sdrNode.binary || !sdrNode.binary.data) {
  const nodeJson = sdrNode?.json || {};
  const reason = nodeJson.error?.message
    || (nodeJson._excel_pending ? 'ExcelJS unavailable — fallback path taken (no binary output)' : 'No binary produced')
    || 'Unknown reason';
  console.error('SDR Excel binary missing:', reason);
  return [{ json: { _sdr_upload_skipped: true, folderId, reason: 'Excel binary missing: ' + reason } }];
}

const fileName = sdrNode.binary.data.fileName;
const binaryData = sdrNode.binary.data;

console.log('=== Prepare SDR Excel for Upload ===');
console.log('Folder ID:', folderId);
console.log('File:', fileName);

return [{
  json: { folderId, fileName, _sdr_upload_skipped: false },
  binary: { data: binaryData }
}];

// Extract SDR Excel upload result from Google Drive
// Handles both: successful upload and gracefully-skipped upload

const item = $input.first().json;

// Case: upload was skipped (folder or binary not available)
if (item._sdr_upload_skipped === true) {
  console.warn('=== SDR Excel Upload SKIPPED ===');
  console.warn('Reason:', item.reason);
  return [{
    json: {
      success: false,
      skipped: true,
      reason: item.reason,
      webViewLink: null,
      fileId: null,
      fileName: null,
      folder: 'SDR'
    }
  }];
}

// Case: successful upload — item is the Google Drive API response
console.log('=== SDR Excel Uploaded to Google Drive ===');
console.log('File:', item.name);
console.log('Link:', item.webViewLink);

return [{
  json: {
    success: true,
    skipped: false,
    fileId: item.id,
    fileName: item.name,
    mimeType: item.mimeType,
    webViewLink: item.webViewLink,
    webContentLink: item.webContentLink,
    createdTime: item.createdTime,
    folder: 'SDR'
  }
}];

// ── SDR JSON File Generator ─────────────────────────────────────────────
// SDR 결과를 JSON 파일로 패키징 → Google Drive 업로드 후 TSD 단계에서 수동 로드 가능
// TSD /trigger/tsd 가 기대하는 { clientName, sdrData } 구조로 저장

const parseOut    = $('Parse SDR Output').first().json;
const clientName  = parseOut.clientName || 'Client';
const folderId    = $('Prepare SDR for Upload').first().json.folderId || null;
const sdrFull     = parseOut.sdr;                    // evars, props, events, section_a_ootb, etc.
const tsdPayload  = parseOut.tsdWebhookPayload || {}; // 사전 빌드된 TSD 입력 페이로드

const nowTs = new Date();
const ts    = nowTs.toISOString()
                .replace(/[-:T]/g,'')
                .replace(/\.\d+Z$/,'')
                .substring(0,14); // YYYYMMDDHHMMSS
const tsFormatted = ts.substring(0,8) + '_' + ts.substring(8); // YYYYMMDD_HHMMSS
const fileName = `${clientName}_SDR_${tsFormatted}.json`;

// TSD/Tags 워크플로우에서 직접 로드 가능한 구조로 패키징
const sdrPackage = {
  _meta: {
    generator:   'Tagging AI - SDR Workflow v2.0',
    clientName:  clientName,
    generatedAt: nowTs.toISOString(),
    fileName:    fileName,
    usage:       'TSD 또는 Tags 워크플로우 수동 트리거 시 /trigger/tsd 또는 /trigger/tags 의 body로 사용',
    tsd_endpoint: 'POST /trigger/tsd  →  { clientName, sdrData }',
    tags_endpoint:'POST /trigger/tags →  { clientName, sdrData }'
  },
  clientName: clientName,
  sdrData:  sdrFull,
  stats:    parseOut.stats    || {},
  validation: parseOut.validation || {}
};

const jsonStr = JSON.stringify(sdrPackage, null, 2);
const b64     = Buffer.from(jsonStr, 'utf8').toString('base64');

console.log(`📄 SDR JSON 파일 생성: ${fileName}  (${jsonStr.length} bytes)`);
console.log(`   eVars:${(sdrFull?.evars||[]).length}  Props:${(sdrFull?.props||[]).length}  Events:${(sdrFull?.events||[]).length}`);

return [{
  json: {
    folderId,
    fileName,
    clientName,
    _json_size:   jsonStr.length,
    _upload_skip: !folderId
  },
  binary: {
    data: {
      data:     b64,
      mimeType: 'application/json',
      fileName: fileName
    }
  }
}];

// SDR JSON 파일 Google Drive 업로드 결과 수집
const item = $input.first().json;

// 업로드 스킵 케이스 (folderId 없음)
if (!item.id && !item.name) {
  console.warn('=== SDR JSON Upload SKIPPED ===');
  return [{
    json: {
      success:     false,
      skipped:     true,
      reason:      'folderId missing — Google Drive folder not created',
      webViewLink: null,
      fileId:      null,
      fileName:    null
    }
  }];
}

console.log('=== SDR JSON Uploaded to Google Drive ===');
console.log('File:', item.name);
console.log('Link:', item.webViewLink);

return [{
  json: {
    success:        true,
    skipped:        false,
    fileId:         item.id,
    fileName:       item.name,
    mimeType:       item.mimeType,
    webViewLink:    item.webViewLink,
    webContentLink: item.webContentLink,
    createdTime:    item.createdTime
  }
}];
